import React, { useEffect, useState } from "react";
import axios from "axios";
import config from "../config";

const AdminPayments = () => {
  const [orders, setOrders] = useState([]);
  const [search, setSearch] = useState("");

  const today = new Date().toISOString().split("T")[0];
  const yesterdayDate = new Date(Date.now() - 86400000)
    .toISOString()
    .split("T")[0];

  const fetchOrders = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await axios.get(`${config.apiUrl}/admin/orders`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      const sorted = res.data.sort(
        (a, b) => new Date(b.created_at) - new Date(a.created_at)
      );
      setOrders(sorted);
    } catch (error) {
      console.error("❌ Admin Orders Fetch Error:", error.response);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const filtered = orders.filter((item) => {
    const dateOnly = item.created_at.split("T")[0];
    return (
      item.customer_name.toLowerCase().includes(search.toLowerCase()) ||
      String(item.order_id).includes(search) ||
      dateOnly.includes(search) ||
      item.customer_address.toLowerCase().includes(search.toLowerCase())
    );
  });

  const calcTotal = (date) =>
    orders
      .filter((o) => o.created_at.split("T")[0] === date)
      .reduce((sum, o) => sum + Number(o.amount || 0), 0);

  const todayTotal = calcTotal(today);
  const yesterdayTotal = calcTotal(yesterdayDate);

  const boxStyle = {
    padding: "15px 20px",
    borderRadius: "12px",
    background: "#2B2A4C",
    color: "white",
    minWidth: "200px",
    textAlign: "center",
    boxShadow: "0 0 10px rgba(0,0,0,0.2)",
  };

  const tableStyle = {
    width: "100%",
    borderCollapse: "collapse",
    background: "white",
    borderRadius: "10px",
    overflow: "hidden",
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Poppins" }}>
      <h2 style={{ background: "#8B1874", color: "white", padding: 12, borderRadius: 8 }}>
        💰 Admin Payments Dashboard
      </h2>

      <div style={{ display: "flex", gap: "20px", marginTop: "20px" }}>
        <div style={boxStyle}>
          <h3>Today's Revenue</h3>
          <h2>₹{todayTotal.toLocaleString()}</h2>
        </div>
        <div style={boxStyle}>
          <h3>Yesterday's Revenue</h3>
          <h2>₹{yesterdayTotal.toLocaleString()}</h2>
        </div>
        <div style={boxStyle}>
          <h3>Total Orders</h3>
          <h2>{orders.length}</h2>
        </div>
      </div>

      <input
        type="text"
        placeholder="Search by name, order id, date, address..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{
          width: "100%",
          padding: "10px",
          margin: "20px 0",
          borderRadius: "6px",
          border: "2px solid #8B1874",
        }}
      />

      <table style={tableStyle}>
        <thead style={{ background: "#8B1874", color: "white" }}>
          <tr>
            <th style={{ padding: 10 }}>Order ID</th>
            <th style={{ padding: 10 }}>Customer</th>
            <th style={{ padding: 10 }}>Amount</th>
            <th style={{ padding: 10 }}>Date</th>
            <th style={{ padding: 10 }}>Address</th>
          </tr>
        </thead>
        <tbody>
          {filtered.length === 0 ? (
            <tr>
              <td colSpan="5" style={{ textAlign: "center", padding: 20 }}>
                No Orders Found
              </td>
            </tr>
          ) : (
            filtered.map((order, index) => (
              <tr key={index}>
                <td style={{ padding: 10 }}>{order.order_id}</td>
                <td style={{ padding: 10 }}>{order.customer_name}</td>
                <td style={{ padding: 10 }}>₹{order.amount}</td>
                <td style={{ padding: 10 }}>
                  {order.created_at.split("T")[0]}
                </td>
                <td style={{ padding: 10 }}>{order.customer_address}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AdminPayments;
